/* Prepared presentation cases, applied once. All sample decisions and answers are labeled. */
workspaceKeys.push('vivaRecords','demoCase');
function exampleForms(team){if(team.id==='07')return {1:{title:team.title,problem:'Farmers cannot reliably distinguish early leaf disease from nutrient deficiency using visual inspection alone.',users:'Small-scale farmers and agricultural extension officers reviewing leaf photographs.',research:'Demo literature comparison: a compact CNN classifier versus transfer learning with MobileNet. A held-out field-image set is needed to test generalization.',objectives:'Classify healthy and diseased leaves and display the confidence score with an explanation heatmap.',solution:'A mobile-friendly image upload interface calls a trained image classifier and returns the prediction with a saliency visualization.',success:'Planned target: at least 85% macro F1 on a held-out dataset. This target is illustrative, not a measured result.',evidence:'Demo evidence plan: dataset source, preprocessing notebook, training configuration and held-out evaluation report.'}};return {1:{title:team.title,problem:'Students struggle to find consistent answers to campus policy and timetable questions across English and Kannada.',users:'CS AI students, department office staff and faculty answering repeated campus queries.',research:'Compared keyword search with multilingual retrieval over approved campus documents. Retrieval quality and unsupported answers need separate evaluation.',objectives:'Retrieve relevant approved documents and answer student questions with source citations in English and Kannada.',solution:'A multilingual document retriever selects source passages, then a local language model drafts an answer with document references.',success:'Planned targets: 90% retrieval recall on a curated query set and no unsupported claims in a manual citation audit. These targets are demo assumptions.',evidence:'Demo planning artifacts: query list, source inventory, retrieval comparison and citation-audit checklist.'},2:{functional:'FR1: Ingest approved campus documents. FR2: Accept English and Kannada questions. FR3: Return answers with clickable source citations.',nonfunctional:'NFR1: Target end-to-end response under 8 seconds on the evaluation machine. NFR2: Reject questions with insufficient source evidence. NFR3: Restrict document updates to authorized staff.',architecture:'Student web interface → multilingual retrieval API → document index → local model → cited answer.',implementation:'Draft: chunk approved documents, generate multilingual embeddings, retrieve top passages and generate a grounded answer.',testing:'Draft test plan: bilingual retrieval queries, missing-source refusals and a manual citation correctness audit.',results:'Not submitted. Implementation and evaluation are still in progress; no measured result is claimed.',reflection:'Need to test code-switching, stale documents and the latency of a local model.',evidence:'Stage 2 draft: implementation commits and a walkthrough video will be attached before submission.'}}}
function preparedViva(w,n){const previous=state;let questions;try{state={...state,forms:w.forms};questions=coachQuestions(n)}finally{state=previous}const answers={};questions.forEach((q,i)=>{const value=w.forms[n][q.sourceField];answers[i]='Demo team answer: Our submitted '+q.sourceField+' section states “'+value+'”. '+({problem:'We would validate this with coordinator interviews and a recorded example of a timetable clash.',research:'We compared hard-constraint satisfaction first, then soft-preference quality. The trade-off is solution quality versus solver runtime.',solution:'Each scheduling input is validated before the solver runs. The generated timetable is checked again before export.',success:'We use an anonymized department dataset, count hard-constraint violations and compare runtime against a manual scheduling baseline.',objectives:'We turn each objective into an acceptance test and record the expected and observed outputs.',functional:'For course import, valid rows should be accepted and an invalid faculty/room reference should be rejected with a clear error.',nonfunctional:'We record dataset size, hardware, elapsed time and constraint-conflict count. A run that violates a hard constraint fails even if it is fast.',architecture:'The interface sends validated course, faculty and room data to the API. The API invokes the solver and stores only a validated timetable.',testing:'We include overlapping faculty assignments, full rooms and unavailable slots as negative cases, and expect explicit rejection.',results:'These are prepared demonstration results only. In a real submission we would attach the reproducible benchmark log and commit identifier.'}[q.sourceField]||'We would provide a reproducible test and repository evidence for this claim.')});return {stage:n,questions,answers,source:'Prepared demo · submission-coach questions and illustrative team answers'}}
function prepareCases(){if(state.demoCasesVersion===1)return;syncTeam();
 const complete=state.workspaces['03'];if(complete){complete.status1='Approved';complete.status2='Approved';complete.unlocked=true;complete.stage=2;complete.demoCase='Both stages complete';complete.feedback='Demo faculty approval: Both stages are complete. The team has documented the design, validation plan and viva responses. Prepared for HOD demonstration.';complete.score=9;complete.reviews={1:{feedback:'Demo faculty review: Clear problem, stakeholders and success criteria. Stage 1 approved; Stage 2 unlocked.',score:8,comments:{}},2:{feedback:complete.feedback,score:9,comments:{}}};complete.vivaRecords=[preparedViva(complete,1),preparedViva(complete,2)];const last=complete.vivaRecords[1];complete.questions=last.questions;complete.answers=last.answers;complete.questionStage=2;complete.questionSnapshot=JSON.stringify(complete.forms[2]);complete.activities.unshift({text:'Demo case: both stages approved and 10 viva responses prepared',time:'Prepared presentation data'});}
 const revision=state.workspaces['07'];if(revision){Object.assign(revision.forms,exampleForms(state.teams.find(t=>t.id==='07')));revision.status1='Revision requested';revision.status2='Locked';revision.unlocked=false;revision.stage=1;revision.demoCase='Stage 1 changes requested';revision.feedback='Demo faculty feedback: Narrow the crop scope, specify the dataset size and split, and turn the objectives into measurable acceptance criteria before approval. Stage 2 remains locked until the revision is accepted.';revision.score=6;revision.reviews={1:{feedback:revision.feedback,score:6,comments:{problem:'Specify which crop and disease classes are in scope. Support the need with at least one stakeholder observation.',objectives:'Add a measurable target for each objective and explain the confidence threshold for uncertain predictions.',success:'Define the dataset size and train/validation/test split. Report macro F1 separately from overall accuracy.'}}};revision.messages=[{author:'Dr. Priya Rao',role:'Faculty',text:'Demo faculty message: Please resolve the three Stage 1 comments before resubmitting. HOD can view the same feedback.',topic:'Faculty feedback',created:'Prepared presentation data'}];revision.activities=[{text:'Demo faculty requested Stage 1 revisions; Stage 2 remains locked',time:'Prepared presentation data'}];}
 const draft=state.workspaces['12'];if(draft){Object.assign(draft.forms,exampleForms(state.teams.find(t=>t.id==='12')));draft.status1='Approved';draft.status2='Draft';draft.unlocked=true;draft.stage=2;draft.demoCase='Stage 2 not submitted';draft.feedback='Demo faculty feedback: Stage 1 approved. Proceed with the bilingual retrieval prototype and record citation correctness. Stage 2 is unlocked and awaits the team submission.';draft.score=8;draft.reviews={1:{feedback:draft.feedback,score:8,comments:{}}};draft.activities=[{text:'Demo faculty approved Stage 1 and unlocked Stage 2',time:'Prepared presentation data'},{text:'Team is working on the Stage 2 draft; not submitted',time:'Prepared presentation data'}];}
 state.demoCasesVersion=1;const current=state.workspaces[state.activeTeamId];if(current){workspaceKeys.forEach(k=>delete state[k]);Object.assign(state,clone(current))}save();
}
prepareCases();
function caseSummary(t){const w=teamStatus(t);if(w.status2==='Approved')return {label:'Both stages complete',tone:'',detail:`${Object.values(w.vivaRecords||{}).reduce((n,r)=>n+Object.values(r.answers||{}).filter(Boolean).length,0)} viva responses · faculty approved`,progress:100};if(w.status1==='Revision requested')return{label:'Stage 1 · Changes requested',tone:'amber',detail:'Inline faculty comments · Stage 2 locked',progress:35};if(w.status1==='Approved'&&w.status2==='Draft')return{label:'Stage 2 · Not submitted',tone:'gray',detail:'Stage 1 approved · Stage 2 unlocked',progress:65};return{label:w.status2==='Submitted'?'Stage 2 · Under review':'Stage 1 · '+w.status1,tone:'gray',detail:'CS AI project workspace',progress:w.status1==='Approved'?65:15}}
function demoCases(){return `<section class="case-grid">${['03','07','12'].map((id,i)=>{const t=state.teams.find(t=>t.id===id);if(!t)return '';const s=caseSummary(t);return `<article class="card case-card"><div class="row"><span class="tiny">CASE ${i+1} · TEAM ${esc(t.id)}</span><span class="case-dot ${s.tone}"></span></div><h2>${esc(s.label)}</h2><p>${esc(t.title)}</p><div class="bar"><i style="width:${s.progress}%"></i></div><p class="mini">${esc(s.detail)}</p><div class="actions"><button class="textbtn" onclick="openCase('${esc(id)}')">Inspect case &nbsp;${ICONS.chevronRight}</button></div></article>`}).join('')}</section><div class="notice">Prepared demonstration states: decisions, results and viva answers in these cases are illustrative. Faculty actions and future submissions update each team independently.</div>`}
function openCase(id){switchTeam(id);if(['HOD','Faculty Admin','Faculty'].includes(state.role))go('Faculty Review');else{const w=teamStatus(activeTeam());state.stage=w.status1==='Revision requested'?1:2;go('Design Journey')}}
const departmentDirectory=department;
department=function(){let html=departmentDirectory();return html.includes('<!-- DEMO_CASES -->')?html.replace('<!-- DEMO_CASES -->',demoCases()):html.replace('<div class="stats">',demoCases()+'<div class="stats">')};
rosterRows=function(filter){return state.teams.filter(t=>JSON.stringify(t).toLowerCase().includes(filter.toLowerCase())).map(t=>{const w=teamStatus(t);return `<tr><td><strong>Team ${esc(t.id)}</strong> ${t.sample?'<span class="tag gray">Dummy</span>':''}<p>${esc(t.title)}</p></td><td><strong>${esc(t.faculty)}</strong><p class="mini">CS AI<br>Admin: ${esc(t.facultyAdmin)}</p></td><td>${t.members.map((m,i)=>`<div class="roster-member"><strong>${esc(m.name)}${i===0?' · Lead':''}</strong><small>${esc(m.usn)}</small></div>`).join('')}</td><td>${esc(t.topic)}<p><span class="tag ${w.status1==='Revision requested'?'amber':''}">Stage 1 · ${esc(w.status1)}</span></p><p><span class="tag ${w.status2==='Locked'?'gray':''}">Stage 2 · ${esc(w.status2)}</span></p></td><td><button class="textbtn" onclick="openCase('${esc(t.id)}')">Review &nbsp;${ICONS.chevronRight}</button><button class="textbtn" onclick="openRosterTeam('${esc(t.id)}')">Portfolio &nbsp;${ICONS.chevronRight}</button></td></tr>`}).join('')||'<tr><td colspan="5">No matching teams.</td></tr>'};
const reviewWithoutComments=review;
review=function(){let html=reviewWithoutComments();const n=state.stage,review=state.reviews?.[n],fields=fieldsets[n];if(!isFaculty())html=`<section class="card"><label for="record-stage">View stage record</label><select id="record-stage" onchange="state.stage=Number(this.value);save();render()"><option value="1" ${n===1?'selected':''}>Stage 1 · Discovery</option><option value="2" ${n===2?'selected':''}>Stage 2 · Requirements & realization</option></select></section>`+html;html+=`<section class="card"><h2>Stage ${n} · Section-by-section faculty comments</h2><p class="mini">The Team Lead and HOD see these same comments on the stage form.</p>${fields.map(([key,label])=>isFaculty()?`<label for="review-note-${key}">${label}</label><textarea id="review-note-${key}" class="review-note" placeholder="Optional specific feedback for this section…">${esc(review?.comments?.[key]||'')}</textarea>`:review?.comments?.[key]?`<div class="field-feedback"><strong>${esc(label)}</strong><p>${esc(review.comments[key])}</p></div>`:'').join('')}${!isFaculty()&&!Object.values(review?.comments||{}).some(Boolean)?'<p class="mini">No section-specific comments recorded for this stage.</p>':''}</section>`;
 if(state.vivaRecords?.length)html+=`<section class="card"><div class="card-head"><h2>Viva questions & team responses</h2><span class="tag amber">PREPARED DEMO ANSWERS</span></div><p class="mini">${state.vivaRecords.reduce((n,r)=>n+r.questions.length,0)} questions answered across both stages. These are illustrative responses, not a verified AI assessment.</p>${state.vivaRecords.map(r=>`<details class="viva-record" ${r.stage===n?'open':''}><summary>Stage ${r.stage} · ${r.questions.length} answered questions</summary>${r.questions.map((q,i)=>`<article class="question"><span class="badge-num">QUESTION ${i+1} · ${esc(q.source)}</span><p>${esc(q.text)}</p><small>${esc(q.context)}</small><div class="demo-answer"><strong>Team response · demo</strong><p>${esc(r.answers[i])}</p></div></article>`).join('')}</details>`).join('')}</section>`;
 return html+submittedVivaRecords()};
const journeyWithoutComments=journey;
journey=function(){let html=journeyWithoutComments();const comments=state.reviews?.[state.stage]?.comments||{};Object.entries(comments).forEach(([key,text])=>{if(!text)return;const re=new RegExp('(<(?:textarea|input) id="f-'+key+'"[^>]*>(?:[\\s\\S]*?<\\/textarea>)?)');html=html.replace(re,(_,field)=>field+`<div class="field-feedback"><strong>Faculty requested change</strong><p>${esc(text)}</p></div>`)});return html};
const saveDecisionWithScope=decide;
decide=function(approve){const n=state.stage;if(!isFaculty()||status(n)!=='Submitted')return saveDecisionWithScope(approve);const comments={};fieldsets[n].forEach(([key])=>{const field=$('#review-note-'+key);if(field?.value.trim())comments[key]=field.value.trim()});saveDecisionWithScope(approve);if(state.reviews?.[n]&&state['status'+n]===(approve?'Approved':'Revision requested')){state.reviews[n].comments=comments;save();render()}};
const earlierOverview=overview;
overview=function(){let html=earlierOverview();if(['Team Lead','Faculty'].includes(state.role)&&state.demoCase)html=`<div class="notice"><strong>Presentation case · ${esc(state.demoCase)}</strong><br>Prepared sample state for demonstration. Faculty: ${esc(state.guide)} · CS AI</div>`+html;return html};
const renderAllCases=render;
render=function(){renderAllCases();const ring=document.querySelector('.ring');if(ring){const angle=caseSummary(activeTeam()).progress*3.6;ring.style.background=`conic-gradient(var(--brand) 0deg ${angle}deg, rgba(255, 255, 255, 0.18) ${angle}deg)`}};
save();render();
